#!/usr/bin/env python3
"""LSP driver for probing `zk lsp` (JSON-RPC over stdio, Content-Length framing)."""
import json, os, select, subprocess, sys, time

ZK = "/workspace/executable"
LOGDIR = "/tmp/specs/lsp"


class LSP:
    def __init__(self, cwd, extra_args=None, env=None):
        args = [ZK, "lsp"] + (extra_args or [])
        e = dict(os.environ)
        if env:
            e.update(env)
        self.proc = subprocess.Popen(args, cwd=cwd, stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=e)
        self.rawlog = []   # list of (direction, bytes)
        self.buf = b""
        self.stderr_data = b""

    def send_obj(self, obj, label=""):
        body = json.dumps(obj, separators=(",", ":")).encode()
        self.send_raw(b"Content-Length: %d\r\n\r\n" % len(body) + body, label or obj.get("method", str(obj.get("id"))))

    def send_raw(self, data, label=""):
        try:
            self.proc.stdin.write(data)
            self.proc.stdin.flush()
        except BrokenPipeError:
            pass
        self.rawlog.append(("SEND", label, data))

    def close_stdin(self):
        try:
            self.proc.stdin.close()
        except Exception:
            pass

    def _pump(self, timeout):
        end = time.time() + timeout
        got = False
        while time.time() < end:
            r, _, _ = select.select([self.proc.stdout, self.proc.stderr], [], [], max(0, end - time.time()))
            if not r:
                break
            for f in r:
                chunk = os.read(f.fileno(), 65536)
                if f is self.proc.stdout:
                    if chunk:
                        self.buf += chunk
                        got = True
                else:
                    if chunk:
                        self.stderr_data += chunk
        return got

    def recv_msg(self, timeout=5.0):
        """Read one framed message; returns (headers, body_bytes) or None."""
        end = time.time() + timeout
        while time.time() < end:
            sep = self.buf.find(b"\r\n\r\n")
            if sep == -1:
                if not self._pump(end - time.time()):
                    break
                continue
            headers = self.buf[:sep]
            clen = None
            for line in headers.split(b"\r\n"):
                if line.lower().startswith(b"content-length:"):
                    clen = int(line.split(b":", 1)[1].strip())
            if clen is None:
                raise ValueError("no content-length in %r" % headers)
            if len(self.buf) < sep + 4 + clen:
                if not self._pump(end - time.time()):
                    break
                continue
            body = self.buf[sep + 4: sep + 4 + clen]
            rest = self.buf[sep + 4 + clen:]
            self.rawlog.append(("RECV", "", headers + b"\r\n\r\n" + body))
            self.buf = rest
            return headers, body
        return None

    def recv_all(self, timeout=2.0, idle=0.4):
        """Collect messages until idle for `idle` secs or overall `timeout`."""
        msgs = []
        end = time.time() + timeout
        while time.time() < end:
            m = self.recv_msg(timeout=idle)
            if m is None:
                break
            msgs.append(m)
        # drain any leftover unparsed bytes
        self._pump(0.2)
        return msgs

    def finish(self, wait=3.0):
        try:
            rc = self.proc.wait(timeout=wait)
        except subprocess.TimeoutExpired:
            self.proc.kill()
            rc = self.proc.wait()
        # drain remaining stderr
        try:
            rest = self.proc.stderr.read()
            if rest:
                self.stderr_data += rest
        except Exception:
            pass
        return rc


def dump_log(lsp, path, note=""):
    with open(path, "w") as f:
        if note:
            f.write("# " + note + "\n\n")
        for direction, label, data in lsp.rawlog:
            f.write("=== %s %s ===\n" % (direction, label))
            f.write(repr(data) + "\n\n")
        f.write("=== STDERR ===\n")
        f.write(repr(lsp.stderr_data) + "\n")

